<?php
require_once 'inc/db.php';require_once 'inc/auth.php';
if(isset($_POST['read_all'])){$s=$db->prepare('UPDATE tbl_notifications SET is_read=1 WHERE user_id=?');$s->execute([$_SESSION['user_id']]);}
if(isset($_GET['open'])){$s=$db->prepare('SELECT report_id FROM tbl_notifications WHERE notif_id=? AND user_id=?');$s->execute([(int)$_GET['open'],$_SESSION['user_id']]);$rid=$s->fetchColumn();if($rid){$db->prepare('UPDATE tbl_notifications SET is_read=1 WHERE notif_id=?')->execute([(int)$_GET['open']]);header('Location: view_report.php?id='.(int)$rid);exit;}}
$s=$db->prepare('SELECT * FROM tbl_notifications WHERE user_id=? ORDER BY created_at DESC');$s->execute([$_SESSION['user_id']]);$items=$s->fetchAll(PDO::FETCH_ASSOC);$page_title='Notifications';include 'inc/links.php';include 'inc/header.php';?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php';?><section role="main" class="content-body"><?php include 'inc/inner-header.php';?><section class="panel"><header class="panel-heading"><form method="post" class="pull-right"><button name="read_all" class="btn btn-xs btn-default">Mark all read</button></form><h2 class="panel-title"><i class="fa fa-bell"></i> Updates</h2></header><div class="panel-body notification-list"><?php foreach($items as $n):?><a class="notification-item <?php echo !$n['is_read']?'unread':'';?>" href="notifications.php?open=<?php echo (int)$n['notif_id'];?>"><i class="fa fa-<?php echo $n['is_read']?'envelope-open':'envelope';?>"></i><span><strong><?php echo e($n['title']);?></strong><br><?php echo e($n['message']);?><small><?php echo date('d M Y H:i',strtotime($n['created_at']));?></small></span></a><?php endforeach;?><?php if(!$items):?><p class="text-center text-muted">You have no notifications.</p><?php endif;?></div></section></section></div><?php include 'inc/scripts.php';?>
